import{_ as t,c as a,o as i,a0 as o}from"./chunks/framework.oTSD2LDJ.js";const k=JSON.parse('{"title":"UDCText","description":"","frontmatter":{"title":"UDCText","editLink":true},"headers":[],"relativePath":"component-encyclopedia/UDCText.md","filePath":"zh/component-encyclopedia/UDCText.md"}'),l={name:"component-encyclopedia/UDCText.md"};function s(n,e,d,r,c,p){return i(),a("div",null,e[0]||(e[0]=[o(`<h1 id="udctext-组件" tabindex="-1">UDCText 组件 <a class="header-anchor" href="#udctext-组件" aria-label="Permalink to &quot;UDCText 组件&quot;">​</a></h1><p>文本显示组件，是 Uniquenium 中最常用的组件之一。支持字体、颜色、对齐、样式等完整文本属性配置，内置 <code>%{}</code> 表达式引擎可实现动态数据显示（如 CPU 使用率、电量、时间等实时数据）。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>组件类型</td><td>内置组件（UDC）</td></tr><tr><td>源文件</td><td><code>UniDesk/Components/UDCText/UDCText.qml</code></td></tr><tr><td>继承</td><td><code>UniDeskComBase</code> → <code>UniDeskComBox</code> → <code>UniDeskObject</code></td></tr></tbody></table><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2><h3 id="文本内容" tabindex="-1">文本内容 <a class="header-anchor" href="#文本内容" aria-label="Permalink to &quot;文本内容&quot;">​</a></h3><ul><li><code>property string textContent</code>：文本内容。支持 <code>%{变量名}</code> 表达式语法，通过 <code>UniDeskExpr</code> 自动解析。默认值：<code>&quot;文字&quot;</code></li></ul><h3 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h3><ul><li><code>property color textColor</code>：文字颜色。默认跟随主题：浅色黑色，深色白色</li><li><code>property color styleColor</code>：强调色。用于高亮/链接样式。默认取 <code>UniDeskSettings.primaryColor</code></li><li><code>property int textFormat</code>：文本格式（<code>Text.PlainText</code> / <code>Text.RichText</code> / <code>Text.MarkdownText</code>）。默认：<code>Text.RichText</code></li><li><code>property int wrapMode</code>：换行模式。默认：<code>Text.Wrap</code></li></ul><h3 id="字体" tabindex="-1">字体 <a class="header-anchor" href="#字体" aria-label="Permalink to &quot;字体&quot;">​</a></h3><ul><li><code>property string fontFamily</code>：字体家族。默认取 <code>UniDeskTextStyle.family</code></li><li><code>property real fontSize</code>：字号（像素）。默认：30</li><li><code>property bool bold</code>：是否加粗。默认：<code>false</code></li><li><code>property bool italic</code>：是否斜体。默认：<code>false</code></li><li><code>property bool underline</code>：是否下划线。默认：<code>false</code></li><li><code>property bool strikeout</code>：是否删除线。默认：<code>false</code></li><li><code>property bool smallCaps</code>：是否小型大写字母。默认：<code>false</code></li><li><code>property int weight</code>：字体字重。默认：<code>Font.Normal</code></li><li><code>property int style</code>：字体样式。默认：<code>Text.Normal</code></li></ul><h3 id="间距与对齐" tabindex="-1">间距与对齐 <a class="header-anchor" href="#间距与对齐" aria-label="Permalink to &quot;间距与对齐&quot;">​</a></h3><ul><li><code>property real letterSpacing</code>：字符间距。默认：0</li><li><code>property real wordSpacing</code>：单词间距。默认：0</li><li><code>property real lineHeight</code>：行高倍数。默认：1</li><li><code>property int horizontalAlignment</code>：水平对齐。默认：<code>Text.AlignHCenter</code></li><li><code>property int verticalAlignment</code>：垂直对齐。默认：<code>Text.AlignVCenter</code></li></ul><h2 id="动态表达式" tabindex="-1">动态表达式 <a class="header-anchor" href="#动态表达式" aria-label="Permalink to &quot;动态表达式&quot;">​</a></h2><p>UDCText 通过内部 <code>flushText</code> Timer（50ms 间隔）持续调用 <code>UniDeskExpr.convertStr()</code> 刷新文本内容。支持的 <code>%{}</code> 变量：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>%{cpu}</code></td><td>CPU 使用率</td></tr><tr><td><code>%{mem}</code></td><td>内存使用率</td></tr><tr><td><code>%{net}</code></td><td>网络下载速率</td></tr><tr><td><code>%{bat}</code></td><td>电池百分比</td></tr><tr><td><code>%{date}</code></td><td>当前日期</td></tr><tr><td><code>%{time}</code></td><td>当前时间</td></tr><tr><td><code>%{datetime}</code></td><td>当前日期时间</td></tr></tbody></table><p>也支持通过模板预设传入自定义变量。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 显示 CPU 和电量实时数据</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 在组件编辑器中创建 UDCText，设置 textContent 为：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;CPU: %{cpu}%  电量: %{bat}%&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 显示欢迎信息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;欢迎使用 Uniquenium&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 富文本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;&lt;b&gt;加粗文字&lt;/b&gt; &lt;font color=&#39;red&#39;&gt;红色文字&lt;/font&gt;&quot;</span></span></code></pre></div><h2 id="属性数据导出" tabindex="-1">属性数据导出 <a class="header-anchor" href="#属性数据导出" aria-label="Permalink to &quot;属性数据导出&quot;">​</a></h2><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> propertyDataEx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        textContent, textColorR, textColorG, textColorB, textColorA,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        fontFamily, fontSize, smallCaps, bold, italic, underline, strikeout,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        letterSpacing, wordSpacing, lineHeight, weight, style,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        styleColorR, styleColorG, styleColorB, styleColorA,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        textFormat, wrapMode, horizontalAlignment, verticalAlignment</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../controls-reference/cpp-ext/UniDeskExpr">UniDeskExpr</a> — <code>%{}</code> 表达式引擎</li><li><a href="./../controls-reference/cpp-ext/UniDeskTextStyle">UniDeskTextStyle</a> — 全局字体样式</li><li><a href="./../controls-reference/cpp-ext/UniDeskSettings">UniDeskSettings</a> — <code>primaryColor</code> 主题色</li></ul>`,22)]))}const u=t(l,[["render",s]]);export{k as __pageData,u as default};
